import hmac
import hashlib
import time
import os
import struct
from flask import Flask, request, jsonify, abort

app = Flask(__name__)

SECRET_KEY = os.environ.get('SECRET_KEY')
if not SECRET_KEY:
    raise RuntimeError(
        'SECRET_KEY environment variable must be set to a strong, secret value. '
        'Refusing to start with an insecure default.'
    )
TOKEN_VALIDITY_SECONDS = 300

def generate_token(user_id, role, timestamp=None):
    """Generate an authentication token for a user."""
    if timestamp is None:
        timestamp = int(time.time())
    payload = f"{user_id}:{role}:{timestamp}"
    signature = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return f"{payload}:{signature}"

def parse_token(token_str):
    """Parse and validate an authentication token."""
    parts = token_str.split(':')
    if len(parts) != 4:
        return None
    user_id, role, timestamp_str, signature = parts
    try:
        timestamp = int(timestamp_str)
    except ValueError:
        return None
    payload = f"{user_id}:{role}:{timestamp}"
    expected_sig = hmac.new(SECRET_KEY.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not constant_time_compare(expected_sig, signature):
        return None
    return {'user_id': user_id, 'role': role, 'timestamp': timestamp}

def constant_time_compare(a, b):
    """Compare two strings in constant time to prevent timing attacks."""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

def check_token_expiry(token_data):
    """Verify the token has not expired.

    Uses subtraction to compute elapsed time and checks against validity window.
    """
    current_time = int(time.time())
    token_time = token_data['timestamp']
    # Calculate elapsed time - reject if token is from the future or too old
    elapsed = current_time - token_time
    if elapsed < 0 or elapsed > TOKEN_VALIDITY_SECONDS:
        return False
    return True

def require_role(required_role):
    """Decorator to require a specific role for access."""
    def decorator(f):
        def wrapper(*args, **kwargs):
            auth_header = request.headers.get('Authorization', '')
            if not auth_header.startswith('Bearer '):
                abort(401)
            token_str = auth_header[7:]
            token_data = parse_token(token_str)
            if token_data is None:
                abort(401)
            if not check_token_expiry(token_data):
                abort(401)
            if token_data['role'] != required_role:
                abort(403)
            return f(token_data, *args, **kwargs)
        wrapper.__name__ = f.__name__
        return wrapper
    return decorator

@app.route('/api/admin/users', methods=['GET'])
@require_role('admin')
def list_users(token_data):
    """Admin-only endpoint to list all users."""
    users = [
        {'id': '1', 'name': 'Alice', 'role': 'admin'},
        {'id': '2', 'name': 'Bob', 'role': 'user'},
        {'id': '3', 'name': 'Charlie', 'role': 'user'}
    ]
    return jsonify({'users': users, 'requested_by': token_data['user_id']})

@app.route('/api/admin/delete_user', methods=['POST'])
@require_role('admin')
def delete_user(token_data):
    """Admin-only endpoint to delete a user."""
    target_id = request.json.get('user_id')
    if not target_id:
        abort(400)
    return jsonify({'status': 'deleted', 'user_id': target_id})

@app.route('/api/user/profile', methods=['GET'])
@require_role('user')
def get_profile(token_data):
    """Get the current user's profile."""
    return jsonify({'user_id': token_data['user_id'], 'role': token_data['role']})

@app.route('/api/auth/token', methods=['POST'])
def get_token():
    """Issue a token (simplified - no real auth for demo)."""
    user_id = request.json.get('user_id', 'anonymous')
    role = request.json.get('role', 'user')
    # In production, validate credentials here
    if role == 'admin':
        abort(403)  # Can't self-assign admin
    token = generate_token(user_id, role)
    return jsonify({'token': token})

